from langfuse.decorators import observe, langfuse_context

@observe(name="wake_up_agent_execution", as_type="span")
async def execute_wake_up_agent(trigger_data: Dict, user_id: str) -> WakeUpResult:
    """Execute wake-up agent for a fired trigger."""

    # Update observation with metadata
    langfuse_context.update_current_observation(
        metadata={
            "trigger_id": trigger_data["id"],
            "trigger_type": trigger_data["trigger_type"],
            "user_id": user_id
        }
    )

    # Agent execution logic here...

    # Update observation with output
    langfuse_context.update_current_observation(
        output={
            "skip": result.skip,
            "message_length": len(result.message) if result.message else 0,
            "tools_called": result.tools_called
        }
    )

    return result

import json from dataclasses import dataclass from typing import Optional, List
@dataclass class WakeUpResult: skip: bool skip_reason: Optional[str] message: Optional[str] tools_called: List[str] reasoning: str
def parse_agent_response(response_content: str) -> WakeUpResult: """Parse LLM response into WakeUpResult."""
try: # Try to parse as JSON data = json.loads(response_content)
return WakeUpResult( skip=data.get("skip", False), skip_reason=data.get("skip_reason"), message=data.get("message"), tools_called=data.get("tools_called", []), reasoning=data.get("reasoning", "No reasoning provided") ) except json.JSONDecodeError: # Fallback: treat as plain message logger.warning("Failed to parse agent response as JSON, treating as message") return WakeUpResult( skip=False, skip_reason=None, message=response_content, tools_called=[], reasoning="Fallback: LLM did not return JSON" )

import asyncio

async def execute_with_timeout(coro, timeout_seconds: int = 600):
    """Execute coroutine with timeout."""
    try:
        return await asyncio.wait_for(coro, timeout=timeout_seconds)
    except asyncio.TimeoutError:
        logger.error(f"Agent execution timed out after {timeout_seconds}s")
        return WakeUpResult(
            skip=True,
            skip_reason="Agent execution timeout",
            message=None,
            tools_called=[],
            reasoning="Execution exceeded 10 minute timeout"
        )
